const region=document.documentElement.dataset.region;const currency=region==='au'?'AU$':'£';const theme=document.querySelector('#theme');function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';theme.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');theme.setAttribute('aria-pressed',dark)}syncTheme();theme.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('ron-appearance',document.documentElement.dataset.theme)}catch{}syncTheme()});const dialog=document.querySelector('#invite-dialog');const content=document.querySelector('#invite-content');function start(){content.innerHTML=`<span class="invitation-meta">MEMBER INTRODUCTION</span><h2>A private introduction.</h2><p>An existing member can introduce you. Approved Partners can also invite and onboard their clients directly.</p><form id="code-form"><label for="code">Invitation code</label><input id="code" autocomplete="off" required placeholder="Enter your invitation code"><div class="error" id="code-error" role="alert"></div><button class="button">Continue <span>→</span></button></form><p class="form-note">Concept preview only. Use RON-PREVIEW to try the invitation steps. Nothing is sent.</p>`;content.querySelector('form').addEventListener('submit',event=>{event.preventDefault();if(content.querySelector('input').value.trim().toUpperCase()!=='RON-PREVIEW'){content.querySelector('#code-error').textContent='This invitation is not recognised. In the preview, use RON-PREVIEW.';return}details()})}function details(){content.innerHTML=`<span class="invitation-meta">ILLUSTRATIVE INVITATION · ${region.toUpperCase()}</span><h2>Let’s start with you.</h2><p>A portfolio of ${currency}2m or more is required. Your circumstances and service scope would be reviewed before admission.</p><form id="details-form"><label for="name">Your name</label><input id="name" autocomplete="name" required><label for="email">Email</label><input id="email" type="email" autocomplete="email" required><label for="portfolio">Investable portfolio (${currency})</label><input id="portfolio" type="number" min="2000000" step="1" required placeholder="2,000,000"><label class="check"><input type="checkbox" required><span>I understand that an invitation does not guarantee admission.</span></label><button class="button">Preview introduction <span>→</span></button></form><p class="form-note">Local demonstration. No information is stored or transmitted.</p>`;content.querySelector('form').addEventListener('submit',event=>{event.preventDefault();content.innerHTML=`<span class="invitation-meta">PREVIEW COMPLETE</span><h2>That’s the introduction.</h2><p>In the proposed service, ron. would review the introduction and discuss the right professional support for your portfolio.</p><p>No application has been sent. Your onboarding route, fees and engagement would be confirmed separately.</p><button class="button" id="done">Close preview <span>↗</span></button>`;content.querySelector('#done').addEventListener('click',()=>dialog.close())})}document.querySelectorAll('[data-invite]').forEach(button=>button.addEventListener('click',()=>{start();dialog.showModal()}));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});

const partnerPanel=document.querySelector('#partner-panel');if(partnerPanel){const investorMarkup=partnerPanel.innerHTML;const tabs=[...document.querySelectorAll('[data-partner-tab]')];function showPartnerTab(button){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===button));t.tabIndex=t===button?0:-1});partnerPanel.innerHTML=button.dataset.partnerTab==='investors'?investorMarkup:document.querySelector('#'+button.dataset.partnerTab+'-panel').innerHTML;partnerPanel.setAttribute('aria-labelledby',button.id);bindPartnerEnquiries()}tabs.forEach((button,i)=>{button.tabIndex=i===0?0:-1;button.addEventListener('click',()=>showPartnerTab(button));button.addEventListener('keydown',event=>{let next=i;if(event.key==='ArrowRight')next=(i+1)%tabs.length;else if(event.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();showPartnerTab(tabs[next]);tabs[next].focus()})})}function bindPartnerEnquiries(){document.querySelectorAll('[data-partner-enquire]').forEach(button=>button.addEventListener('click',()=>{content.innerHTML=`<span class="invitation-meta">PARTNER INTRODUCTION · CONCEPT PREVIEW</span><h2>Bring ron. to your firm.</h2><p>Partners need in-house wealth advisory and tax accountancy, the appropriate local permissions, and professional review before advice or tax adjustments reach clients.</p><form id="partner-form"><label for="firm">Firm name</label><input id="firm" required autocomplete="organization"><label for="work-email">Work email</label><input id="work-email" type="email" required autocomplete="email"><label class="check"><input type="checkbox" required><span>Our firm has in-house tax accountancy and wealth advisory.</span></label><label class="check"><input type="checkbox" required><span>Our firm holds the relevant local permissions and registrations.</span></label><button class="button">Preview Partner introduction <span>→</span></button></form><p class="form-note">Local demonstration. Nothing is stored or sent. This does not approve your firm as a Partner.</p>`;dialog.showModal();content.querySelector('form').addEventListener('submit',event=>{event.preventDefault();content.innerHTML=`<span class="invitation-meta">PREVIEW COMPLETE</span><h2>A conversation first.</h2><p>The proposed next step is a discussion of your firm’s services, permissions, client base and onboarding needs. Commercial terms would be shared privately.</p><p>No enquiry was sent and no Partner approval has been granted.</p><button class="button" id="partner-done">Close preview ↗</button>`;content.querySelector('#partner-done').addEventListener('click',()=>dialog.close())})}))}bindPartnerEnquiries();


if(partnerPanel&&new URLSearchParams(location.search).get("for")==="advisers")document.querySelector("#tab-firms").click();

const explanation=document.querySelector('#explain-dialog');
if(explanation){const localPension=region==='au'?'superannuation':'pensions';const minimum=region==='au'?'AU$2m':'£2m';const contentByTopic={
own:`<h2 id="explain-title">If you own it, see it.</h2><p>Shares. Gold. Property. Cash. ${localPension.charAt(0).toUpperCase()+localPension.slice(1)}. Options from work. Investments held personally or through a company.</p><p>ron. is designed to show the whole picture whenever you want it: what you own, what it’s worth, who owns it and what it pays. A company holding other assets doesn’t make your wealth count twice.</p><p>You don’t need to wait for a report to understand your own money.</p>`,
plan:`<h2 id="explain-title">Ask before you invest.</h2><p>“I’ve got cash to invest.” “I want to buy gold.” “Can I stop working?” Tell ron. what you want to do.</p><p>The plan considers your salary, existing holdings and available limits. Should you invest personally, through your investment company or another suitable structure? What tax could arise? What would be left to spend?</p><p>You can see the relevant rules, assumptions and trade-offs in plain language. Your Partner approves recommendations and tax adjustments before they reach you. You choose what to do.</p><div class="explain-note">The aim is to minimise tax within the law, using suitable allowances, reliefs and structures. No hidden income, tax evasion or guaranteed savings.</div>`,
approve:`<h2 id="explain-title">You shouldn’t need a second job to manage your money.</h2><p>There’s the investing. Then there’s income tax, capital gains, company returns, loan agreements, employee options, ${localPension}, contribution limits, retirement planning and family arrangements.</p><p>Moving overseas adds travel records, residency tests and possible tax liabilities in more than one country. A day counter helps keep the evidence; the full residency position still needs professional review.</p><p>ron. is designed to prepare the routine work. Your qualified accountant checks tax returns and filings. A qualified lawyer reviews legal documents and structures where needed.</p><p>You see the draft and what it means. You approve the relevant submission. Your authorised professional files it and keeps the receipt. Each return keeps its own deadline.</p><div class="explain-note">${region==='uk'?'Pension limits, retirement income and inheritance tax belong in the plan.':'Super contribution limits, retirement income and beneficiary arrangements belong in the plan.'} Xero is optional and recommended for expenses and bookkeeping.</div>`,
price:`<h2 id="explain-title">£10,000 a year.</h2><p>A flat annual price for the standard ron. platform per family office, regardless of portfolio size.</p><p>Advice, accounting, legal work and filings are charged separately by the relevant firm. Future optional modules may be priced separately. Any applicable taxes are confirmed in your proposal.</p><p>${region==='au'?'The public price is in GBP; Australian billing terms are agreed in your proposal. ':''}A ${minimum} minimum portfolio applies. Individual platform accounts for shareholders of a participating investment company are included.</p>`,
about:`<h2 id="explain-title">A working mock-up.</h2><p>This site describes the service being designed. It does not currently give personal investment or tax advice, execute instructions, connect to Xero or submit returns.</p><p>Professional appointments, local permissions, integrations and service agreements must be in place before launch. Recommendations and tax adjustments require Partner approval; client authority to act or file is separate.</p>`};document.querySelectorAll('[data-explain]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#explain-content').innerHTML=contentByTopic[button.dataset.explain];explanation.showModal()}));explanation.querySelector('.close').addEventListener('click',()=>explanation.close());explanation.addEventListener('click',event=>{if(event.target===explanation){const b=explanation.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)explanation.close()}})}

const objectiveButtons=[...document.querySelectorAll('[data-goal]')];if(objectiveButtons.length){const objectives={grow:['Give the next pound a job.','Reinvest income you don’t need today, with long-term growth as the goal.','Which holdings belong personally or in a company. Available allowances and reliefs. Future tax bills. How much cash needs to stay accessible.'],balance:['Some for later. Some for living.','Build the portfolio while planning an income you can use now.','Expected receipts, spending needs and tax reserves. When to reinvest, when to take income, and how withdrawals affect the longer-term plan.'],return:['Make the portfolio useful now.','Plan for regular income to support your spending.','Payment dates, liquidity and the tax on money you take out. Enough accessible cash for the gaps, with the risks and sustainability checked by your Partner.']};function chooseObjective(button){objectiveButtons.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1});const goalNames={grow:'Grow your portfolio',balance:'Growth and income',return:'Regular income'};['decision-goal','mobile-decision-goal'].forEach(id=>{const label=document.getElementById(id);if(label)label.textContent=goalNames[button.dataset.goal]});const d=objectives[button.dataset.goal];const panel=document.querySelector('#goal-result');panel.setAttribute('aria-labelledby',button.id);panel.innerHTML=`<div><span class="result-label">THE PRIORITY</span><h3>${d[0]}</h3><p>${d[1]}</p></div><div><span class="result-label">WHAT RON WORKS THROUGH</span><p>${d[2]}</p></div>`}objectiveButtons.forEach((button,i)=>{button.tabIndex=i===0?0:-1;button.addEventListener('click',()=>chooseObjective(button));button.addEventListener('keydown',event=>{let n=i;if(event.key==='ArrowRight')n=(i+1)%3;else if(event.key==='ArrowLeft')n=(i+2)%3;else if(event.key==='Home')n=0;else if(event.key==='End')n=2;else return;event.preventDefault();chooseObjective(objectiveButtons[n]);objectiveButtons[n].focus()})})}
